<template><div><header class="welcome"><div><span class="eyebrow">Estado de la plataforma</span><h2>{{ greeting }}, {{ auth.usuario.value?.nombre || 'usuario' }}</h2><p>Esta es la base operativa para consultar tus mediciones eléctricas.</p></div><span class="status" :class="`status-${realtime.status.value}`"><i></i>{{ realtime.status.value }}</span></header><ErrorState v-if="predio.state.error" :message="predio.state.error" retry @retry="predio.load({force:true})"/><LoadingState v-else-if="predio.state.cargando"/><EmptyState v-else-if="!predio.predios.value.length" title="Aún no tienes predios" message="El backend no devolvió predios asociados a tu cuenta."/><template v-else><section class="grid"><article class="page-card metric"><span>Predio activo</span><strong>{{ predio.predioActual.value?.nombre }}</strong><small>Rol: {{ predio.predioActual.value?.rol }}</small></article><article class="page-card metric"><span>Tiempo real</span><strong>{{ realtime.status.value === 'conectado' ? 'Conectado' : 'En preparación' }}</strong><small>Canal protegido por JWT</small></article><article class="page-card metric"><span>Variables disponibles</span><strong>5</strong><small>Energía · Potencia · Voltaje · Corriente · FP</small></article></section><section class="page-card roadmap"><div><span class="eyebrow">Siguiente etapa</span><h3>Todo listo para construir las ventanas operativas</h3><p>El contexto global de predio, autenticación, rutas protegidas y tiempo real ya está preparado. Las vistas de analítica, alertas e historial se implementarán sobre esta base cuando se validen sus contratos específicos.</p></div><div class="flow"><span>PZEM</span><b>→</b><span>ESP32</span><b>→</b><span>MQTT</span><b>→</b><span>API</span></div></section></template></div></template>
<script setup>import { computed } from 'vue';import LoadingState from '../components/common/LoadingState.vue';import EmptyState from '../components/common/EmptyState.vue';import ErrorState from '../components/common/ErrorState.vue';import { useAuthStore } from '../stores/authStore';import { usePredioStore } from '../stores/predioStore';import { useRealtimeStore } from '../stores/realtimeStore';const auth=useAuthStore();const predio=usePredioStore();const realtime=useRealtimeStore();const greeting=computed(()=>{const h=new Date().getHours();return h<12?'Buenos días':h<18?'Buenas tardes':'Buenas noches'});</script>
<style scoped>.welcome{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:24px}.eyebrow{color:var(--color-muted);font-size:12px;text-transform:uppercase;letter-spacing:.1em}.welcome h2{font-size:32px;margin-top:7px}.welcome p{color:var(--color-muted);margin-top:8px}.status{display:flex;align-items:center;gap:7px;padding:8px 12px;border-radius:var(--radius-pill);background:#eef2f1;color:var(--color-muted);font-size:12px;font-weight:600;text-transform:capitalize}.status i{width:8px;height:8px;border-radius:50%;background:currentColor}.status-conectado{background:#e9f6ee;color:var(--color-success)}.status-reconectando{background:#fff5e3;color:var(--color-warning)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.metric{display:grid;gap:10px;padding:20px}.metric span,.metric small{color:var(--color-muted);font-size:13px}.metric strong{font:600 24px var(--font-display)}.metric small{line-height:1.4}.roadmap{margin-top:16px;padding:24px;display:flex;justify-content:space-between;gap:24px;align-items:center}.roadmap h3{margin-top:8px;font-size:20px}.roadmap p{max-width:650px;margin-top:10px;color:var(--color-muted);line-height:1.55}.flow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;color:var(--color-primary);font-weight:700;font-size:13px}.flow span{padding:8px 10px;background:var(--color-primary-soft);border-radius:var(--radius-sm)}.flow b{color:var(--color-muted)}@media(max-width:700px){.welcome{display:block}.status{width:max-content;margin-top:14px}.welcome h2{font-size:27px}.grid{grid-template-columns:1fr}.roadmap{display:grid}}
